/** @internal Attach sub-resource accessors to a nested element entry. */
function _hydrateWorkbookElement<T extends object>(
  entry: T,
  parentId: string,
  resource: WorkbooksResource,
): DeepReadonly<T> & WorkbookElementSubResources {
  return Object.assign(entry, {
    columns: {
      list: (query?: ListElementColumnsQuery) =>
        resource.listElementColumns(parentId, (entry as any).elementId, query),
      listAll: (query?: ListElementColumnsQuery) =>
        resource.listElementColumnsAll(
          parentId,
          (entry as any).elementId,
          query,
        ),
    },
    lineages: {
      list: () => resource.listLineage(parentId, (entry as any).elementId),
    },
  }) as DeepReadonly<T> & WorkbookElementSubResources;
}

