  /**
   * Create an embed for a workbook
   *
   * Source docs: https://help.sigmacomputing.com/reference/createworkbookembed
   *
   * This endpoint lets you create an embed for a specific workbook. You can embed an entire workbook, a specific page, or an individual element within a workbook. Embedding enables seamless integration of Sigma content into other applications, websites, or internal platforms, providing a flexible and dynamic way to present and interact with data.
   *
   * ### Embedding options
   *
   * - Publicly embed Sigma in a public website by creating an embed of type `public`.
   * - Securely embed Sigma in an authenticated host application.
   *
   *   - (Recommended) Use JSON Web Tokens (JWT) to sign the workbook URL outputted by the [/v2/workbooks](listworkbooks) endpoint instead of the output of this endpoint. See [Create a secure embed](doc:create-a-secure-embed).
   *   - (Deprecated) Use this endpoint to create an embed of type `secure`. This option is deprecated. See [Migrate to JWT-signed secure embed URLs](doc:migrate-to-jwt-signed-secure-embed-urls).
   *
   * ### Usage notes
   * - The endpoint requires the workbookId as a path parameter. Retrieve the **workbookId** by calling the [/v2/workbooks](listworkbooks) endpoint.
   * - The body of the request must specify the type of embed (public).
   * - You must specify the source type (workbook, page, element) and ID for that source to create the embed.
   *
   *   - Retrieve the **pageId** by calling the [/v2/workbooks/{workbookId}/pages](listworkbookpages) endpoint.
   *   - Retrieve the **elementId** by first calling the [/v2/workbooks/{workbookId}/pages](listworkbookpages) endpoint, then calling the [/v2/workbooks/{workbookId}/pages/{pageId}/elements](listworkbookpageelements) endpoint.
   *
   * ### Usage scenarios
   * - **Web application integration:** Developers can use this API to generate the embed URL for integration into their application or for display on a public-facing webpage.
   *
   * ### Best practices
   * - Validate the `workbookId` and `sourceId` to ensure they refer to existing resources before attempting to create an embed.
   * - Consider the security settings of the embed type to match the integration context, ensuring that data exposure is controlled and appropriate for the audience.
   *
   * @param workbookId - Unique identifier of the workbook.
   * @param body - The request body.
   * @returns CreateWorkbookEmbedResponse
   */
  async createEmbed(
    workbookId: string,
    body: CreateWorkbookEmbedBody,
  ): Promise<DeepReadonly<CreateWorkbookEmbedResponse>> {
    const { data, error, response } = await this.client.POST(
      '/v2/workbooks/{workbookId}/embeds',
      { params: { path: { workbookId } }, body },
    );
    if (error) throw new SigmaApiError(error, response);
    return data!;
  }

